create extension if not exists pgcrypto;

do $$ begin
  create type app_role as enum ('admin','teacher','student');
exception when duplicate_object then null; end $$;
do $$ begin create type block_status as enum ('setup','offerings_open','student_open','matching','review','finalized','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type severity_level as enum ('error','warning'); exception when duplicate_object then null; end $$;
do $$ begin create type resolution_status as enum ('open','accepted','resolved'); exception when duplicate_object then null; end $$;
do $$ begin create type capacity_type as enum ('limited','unlimited'); exception when duplicate_object then null; end $$;
do $$ begin create type minimum_applies_to as enum ('section','title'); exception when duplicate_object then null; end $$;
do $$ begin create type matching_preference as enum ('highest_interest','grade_balance'); exception when duplicate_object then null; end $$;
do $$ begin create type below_min_decision as enum ('force_run','cancel'); exception when duplicate_object then null; end $$;

create table if not exists public.users (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique,
  full_name text not null default '',
  role app_role not null default 'student',
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.school_years (id uuid primary key default gen_random_uuid(), label text not null unique, is_active boolean not null default false);
create unique index if not exists one_active_school_year on public.school_years(is_active) where is_active;
create table if not exists public.blocks (id uuid primary key default gen_random_uuid(), school_year_id uuid not null references public.school_years(id) on delete cascade, label text not null, status block_status not null default 'setup', teacher_offerings_open boolean not null default false, student_form_open boolean not null default false, matching_locked boolean not null default false, finalized_at timestamptz, unique(school_year_id,label));
create table if not exists public.teachers (id uuid primary key default gen_random_uuid(), teacher_name text not null unique, sort_order int not null default 0, is_active boolean not null default true);
create table if not exists public.students (id uuid primary key default gen_random_uuid(), student_email text not null unique, student_name text not null, grade int not null check (grade between 3 and 5), teacher_id uuid references public.teachers(id), is_active boolean not null default true, external_student_id text, linked_user_id uuid references public.users(id));
create index if not exists students_teacher_idx on public.students(teacher_id);
create table if not exists public.club_offerings (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, submitted_by_user_id uuid not null references public.users(id), club_title text not null, section_label text, description text not null default '', sponsor_name text not null, meeting_days text[] not null default '{}', capacity_type capacity_type not null default 'limited', max_capacity int, minimum_viable_enrollment int, minimum_applies_to minimum_applies_to not null default 'section', grade_limited boolean not null default false, eligible_grade int check (eligible_grade between 3 and 5), matching_preference matching_preference not null default 'highest_interest', admin_notes text, is_active boolean not null default true, show_to_students boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists club_offerings_block_idx on public.club_offerings(block_id);
create table if not exists public.club_validation_issues (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, club_offering_id uuid references public.club_offerings(id) on delete cascade, severity severity_level not null, field_name text not null, issue_text text not null, resolution_status resolution_status not null default 'open', created_at timestamptz not null default now());
create table if not exists public.student_submissions (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, student_id uuid not null references public.students(id), submitted_by_user_id uuid not null references public.users(id), participation_preference text not null, max_clubs int not null check(max_clubs between 0 and 3), top_choice_club_id uuid references public.club_offerings(id), submitted_at timestamptz not null default now(), is_latest boolean not null default true);
create unique index if not exists one_latest_submission_per_student_block on public.student_submissions(block_id,student_id) where is_latest;
create table if not exists public.student_interest_ratings (id uuid primary key default gen_random_uuid(), student_submission_id uuid not null references public.student_submissions(id) on delete cascade, club_offering_id uuid not null references public.club_offerings(id), interest_level text not null, interest_score int not null check(interest_score between 0 and 3), unique(student_submission_id,club_offering_id));
create table if not exists public.student_validation_issues (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, student_submission_id uuid references public.student_submissions(id) on delete cascade, severity severity_level not null, field_name text not null, issue_text text not null, resolution_status resolution_status not null default 'open', created_at timestamptz not null default now());
create table if not exists public.match_runs (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, run_type text not null default 'initial', started_at timestamptz not null default now(), completed_at timestamptz, status text not null default 'running');
create table if not exists public.draft_assignments (id uuid primary key default gen_random_uuid(), match_run_id uuid not null references public.match_runs(id) on delete cascade, student_id uuid not null references public.students(id), club_offering_id uuid not null references public.club_offerings(id), priority_score numeric not null, fairness_boost numeric not null default 0, was_top_choice boolean not null default false, assignment_pass int not null default 1, unique(match_run_id,student_id,club_offering_id));
create table if not exists public.match_demand_summaries (id uuid primary key default gen_random_uuid(), match_run_id uuid not null references public.match_runs(id) on delete cascade, club_offering_id uuid not null references public.club_offerings(id), positive_interest_count int not null default 0, assigned_count int not null default 0, below_minimum boolean not null default false, at_capacity boolean not null default false, unique(match_run_id,club_offering_id));
create table if not exists public.below_minimum_decisions (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, club_offering_id uuid not null references public.club_offerings(id), decision below_min_decision not null, decided_by_user_id uuid not null references public.users(id), decided_at timestamptz not null default now(), notes text, unique(block_id,club_offering_id));
create table if not exists public.final_assignments (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id) on delete cascade, student_id uuid not null references public.students(id), club_offering_id uuid not null references public.club_offerings(id), finalized_by_user_id uuid not null references public.users(id), finalized_at timestamptz not null default now(), unique(block_id,student_id,club_offering_id));
create table if not exists public.history_snapshots (id uuid primary key default gen_random_uuid(), block_id uuid not null references public.blocks(id), school_year_id uuid not null references public.school_years(id), committed_by_user_id uuid not null references public.users(id), committed_at timestamptz not null default now(), unique(block_id));
create table if not exists public.history_student_outcomes (id uuid primary key default gen_random_uuid(), history_snapshot_id uuid not null references public.history_snapshots(id) on delete cascade, student_id uuid not null references public.students(id), clubs_received int not null, got_top_choice boolean not null, unmet_demand int not null, zero_club_flag boolean not null, unique(history_snapshot_id,student_id));
